export type OnRestEvent = {
    args: {
        id: string;
        args: {
            query: Record<string, unknown>;
            params: Record<string, unknown>;
            body: unknown;
        };
    };
    return: any;
};
export type OnWidgetRestEvent = {
    args: {
        id: string;
        widgetId: string;
        widgetInstanceId: string;
        args: {
            query: Record<string, unknown>;
            params: Record<string, unknown>;
            body: unknown;
        };
    };
    return: any;
};
export type OnRealtimeEvent = {
    args: {
        uri: string;
        event: string;
        data: any;
    };
    return: void;
};
export type RestEvent = {
    args: {
        method: 'get' | 'post' | 'put' | 'delete';
        path: string;
        body: any;
    };
    return: {
        status: number;
        body?: any;
    };
};
export type RealtimeEvent = {
    args: {
        event: string;
        data: any;
    };
    return: void;
};
export type GetOwnerApiTokenEvent = {
    args: void;
    return: string;
};
export type GetLocalUrlEvent = {
    args: void;
    return: string;
};
export type HomeyApiEvents = {
    onRest: OnRestEvent;
    onWidgetRest: OnWidgetRestEvent;
    onRealtime: OnRealtimeEvent;
};
export type SDKApiEvents = {
    rest: RestEvent;
    realtime: RealtimeEvent;
    getOwnerApiToken: GetOwnerApiTokenEvent;
    getLocalUrl: GetLocalUrlEvent;
};
